CREATE TABLE fire_token_plans (id TEXT PRIMARY KEY, name TEXT NOT NULL, duration_days INTEGER NOT NULL CHECK(duration_days BETWEEN 1 AND 36500), token_limit BIGINT NOT NULL CHECK(token_limit BETWEEN 1 AND 1000000000000), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE fire_token_memberships (user_id VARCHAR(36) PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, tenant_id BIGINT NOT NULL, period_id TEXT NOT NULL, plan_id TEXT NOT NULL DEFAULT '', plan_name TEXT NOT NULL DEFAULT '', starts_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, token_limit BIGINT NOT NULL DEFAULT 0 CHECK(token_limit>=0), used_tokens BIGINT NOT NULL DEFAULT 0 CHECK(used_tokens>=0), reserved_tokens BIGINT NOT NULL DEFAULT 0 CHECK(reserved_tokens>=0), suspended BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE fire_token_adjustments (id TEXT PRIMARY KEY, operation_id TEXT NOT NULL UNIQUE, fingerprint TEXT NOT NULL, user_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE, actor_id TEXT NOT NULL, kind TEXT NOT NULL, tokens BIGINT NOT NULL DEFAULT 0, duration_days INTEGER NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT '', before TEXT NOT NULL, after TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX fire_adjustments_user ON fire_token_adjustments(user_id,created_at);
CREATE TABLE fire_model_calls (id TEXT PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE, period_id TEXT NOT NULL, model TEXT NOT NULL DEFAULT '', purpose TEXT NOT NULL DEFAULT '', reserved_tokens BIGINT NOT NULL DEFAULT 0, input_tokens BIGINT NOT NULL DEFAULT 0, output_tokens BIGINT NOT NULL DEFAULT 0, total_tokens BIGINT NOT NULL DEFAULT 0, estimated BOOLEAN NOT NULL DEFAULT FALSE, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, settled_at TIMESTAMPTZ);
CREATE INDEX fire_calls_user_period ON fire_model_calls(user_id,period_id,created_at);
CREATE INDEX fire_calls_recovery ON fire_model_calls(status,created_at);
